	protected Nonconformance read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Nonconformance" );

		Nonconformance entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Nonconformance with primary key" );
		msg.append( nonconformanceId );
		
		NonconformanceFetchOneSummary fetchOneSummary = new NonconformanceFetchOneSummary( nonconformanceId );

		try {
			entity = NonconformanceService.getNonconformanceInstance().getNonconformance( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Nonconformance " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Nonconformance.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Nonconformance." );

		StringBuilder msg = new StringBuilder( "Failed to update a Nonconformance : " );        
		Nonconformance entity = read();
		UpdateNonconformanceCommand command = generateUpdateCommand();
		command.setNonconformanceId(entity.getNonconformanceId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Nonconformance." );

			// for use later on...
			nonconformanceId = entity.getNonconformanceId();

			NonconformanceService proxy = NonconformanceService.getNonconformanceInstance();  

			proxy.updateNonconformance( command ).get();

			LOGGER.info( "-- Successfully saved Nonconformance - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + nonconformanceId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Nonconformance.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Nonconformance." );

		Nonconformance entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Nonconformance with id " + nonconformanceId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Nonconformance with id " + nonconformanceId );

			throw e;
		}

		try{
			NonconformanceService.getNonconformanceInstance().delete( new DeleteNonconformanceCommand( entity.getNonconformanceId() ) ).get();
			LOGGER.info( "-- Successfully deleted Nonconformance with id " + nonconformanceId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Nonconformance with id " + nonconformanceId );

			throw e;
		}
	}

	/**
	 * get all Nonconformances.
	 */
	protected List<Nonconformance> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Nonconformances:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Nonconformance : " );        
		List<Nonconformance> collection  = new ArrayList<>();

		try {
			// call the static get method on the NonconformanceService
			collection = NonconformanceService.getNonconformanceInstance().getAllNonconformance();
			assertNotNull( collection, "An Empty collection of Nonconformance was incorrectly returned.");
			
			// Now print out the values
			Nonconformance entity = null;            
			Iterator<Nonconformance> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getNonconformanceId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

